WITH enriched AS (SELECT id, order_id, carrier, shipped_date, delivered_date, cost, status, PERCENT_RANK() OVER (ORDER BY cost ASC NULLS LAST) AS cost_percent_rank, LEAD(cost, 1, 0) OVER (PARTITION BY order_id ORDER BY delivered_date ASC, id ASC) AS next_cost, FIRST_VALUE(carrier, TRUE) OVER (ORDER BY shipped_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_carrier FROM shipments) SELECT id, order_id, carrier, shipped_date, delivered_date, cost, status, cost_percent_rank, first_known_carrier FROM enriched ORDER BY order_id ASC, status ASC;
